style.css:
@-moz-document domain("roblox.com") {
/* Background image */
    body {
        background: url("https://i.pinimg.com/1200x/79/3b/a6/793ba6c63604c83367deb41691e41f98.jpg") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }

    /* Soft pastel overlay */
    body::before {
        content: "";
        position: fixed;
        top: 0; left: 0;
        width: 100%;
        height: 100%;
        background: rgba(255, 255, 255, 0.35);
        backdrop-filter: blur(4px);
        z-index: -1;
    }

    /* Cards + UI panels */
    .card-item, .game-card, .section-content, .container-list, .rbx-navbar, .menu-option, .content,
    .container-header, .thumbnail-2d-container, .thumbnail-4x3-container {
        border-radius: 14px !important;
        background: rgba(255, 255, 255, 0.55) !important;
        backdrop-filter: blur(6px) !important;
    }

    /* Text color tweaks */
    *, .text, span, p, div {
        color: #3a3a3a !important;
    }

    /* Buttons */
    button, .btn-primary, .btn-control, .btn-secondary {
        background: #ffe6ff !important;
        border-radius: 12px !important;
        border: 2px solid #ffd6ff !important;
        transition: 0.2s;
    }

    button:hover, .btn-primary:hover {
        background: #fff1ff !important;
        transform: scale(1.03);
    }

    /* Remove dark blocks interfering with the style */
    .dark-theme, .light-theme {
        background: transparent !important;
    }
}
